function graphModel(items,recent){const start=Date.parse(recent?'2026-09-17':'2020-01-01'),end=Date.parse('2026-10-16'),max=Math.max(5,Math.ceil(items.length/5)*5);return {start,end,max,points:items.map((d,i)=>({d,count:i+1,x:85+850*(Date.parse(d.date)-start)/(end-start),y:455-355*(i+1)/max}))}}
function drawGraph(items){const m=graphModel(items,recentOnly);let s='<text x="85" y="55">CUMULATIVE MILESTONES IN THIS COLLECTION</text>';for(let v=0;v<=m.max;v+=5){let y=455-355*v/m.max;s+=`<line x1="85" x2="935" y1="${y}" y2="${y}" stroke="#2c4245"/><text x="65" y="${y+4}" text-anchor="end">${v}</text>`}const ticks=recentOnly?['2026-09-17','2026-09-24','2026-10-01','2026-10-08','2026-10-16']:Array.from({length:7},(_,i)=>`${2020+i}-01-01`);for(const t of ticks){let x=85+850*(Date.parse(t)-m.start)/(m.end-m.start);s+=`<text x="${x}" y="485" text-anchor="middle">${recentOnly?t.slice(5):t.slice(0,4)}</text>`}s+='<text x="510" y="520" text-anchor="middle">Publication / announcement date · linear calendar scale</text>';let path='M85 455';for(const p of m.points)path+=` H${p.x} V${p.y}`;path+=' H935';s+=`<path d="${path} L935 455 Z" fill="#d5b67c" opacity=".05"/><path d="${path}" fill="none" stroke="#d5b67c" stroke-width="2.5"/>`;for(const p of m.points){s+=`<g class="plot-point" tabindex="0" role="button" aria-label="${esc(p.d.title)}, ${p.d.date}, milestone ${p.count}" data-plot="${p.d.id}"><title>${esc(p.d.title)} · ${p.d.date} · count ${p.count}</title><circle cx="${p.x}" cy="${p.y}" r="10" fill="transparent"/><circle cx="${p.x}" cy="${p.y}" r="5" fill="${colors[p.d.field]}"/></g>`}$('graph').innerHTML=s;$('graph-table').innerHTML='<table><thead><tr><th>Date</th><th>Milestone</th><th>Cumulative count</th></tr></thead><tbody>'+m.points.map(p=>`<tr><td>${p.d.date}</td><td>${esc(p.d.title)}</td><td>${p.count}</td></tr>`).join('')+'</tbody></table>';document.querySelectorAll('[data-plot]').forEach(e=>{e.onclick=()=>choose(e.dataset.plot);e.onkeydown=k=>{if(k.key==='Enter'||k.key===' '){k.preventDefault();choose(e.dataset.plot)}}})}
